use crate::{events::{Decision,SecuritySnapshot},flow::FlowSnapshot,market::MarketMetrics};
#[derive(Debug,Clone,serde::Serialize)]pub struct OpportunityScore{pub score:f64,pub decision:Decision,pub reasons:Vec<String>}
pub fn score(s:&SecuritySnapshot,f:&FlowSnapshot,m:&MarketMetrics)->OpportunityScore{let mut r=Vec::new();let mut x=0.0;if s.mint_authority_revoked==Some(true){x+=20.0}else{r.push("mint authority not confirmed".into())}if s.freeze_authority_revoked==Some(true){x+=20.0}else{r.push("freeze authority not confirmed".into())}if s.top_10_non_bonding_pct.is_some_and(|v|v<=20.0){x+=20.0}else{r.push("holder concentration unavailable or above threshold".into())}if s.liquidity_usd.is_some_and(|v|v>0.0){x+=15.0}else{r.push("liquidity unavailable".into())}let ratio=if f.sell_sol>0.0{f.buy_sol/f.sell_sol}else{f64::INFINITY};if ratio>=2.0&&f.unique_buyers>=2{x+=15.0}else{r.push("flow gate not met".into())}if m.price_sol.is_some(){x+=10.0}else{r.push("price unavailable".into())}OpportunityScore{score:x.min(100.0),decision:if r.is_empty(){Decision::Pass}else{Decision::Watch},reasons:r}}